// The "offset" (pre-transition) transform/opacity for a given style+direction
// — animating back to transform:none/opacity:1 is what plays the turn.
function pageAnimOffsetStyle(styleId, dir) {
  if (!dir || styleId === "none") return { transform: "none", opacity: 1 };
  const sign = dir === "next" ? -1 : 1; // next turns "away" to the left
  switch (styleId) {
    case "stack":
      return { transform: "scale(0.94) translateY(10px)", opacity: 0.45, transformOrigin: "center" };
    case "flip":
      return {
        transform: `perspective(1000px) rotateY(${sign * -26}deg)`,
        opacity: 0.35,
        transformOrigin: sign < 0 ? "left center" : "right center",
      };
    case "slide":
    default:
      return { transform: `translateX(${sign * 28}px)`, opacity: 0.45, transformOrigin: "center" };
  }
}

