import { store } from "../../store";

// ── Works + lists catalog (metadata only — PDF bytes live in db.js/IndexedDB) ──
const WORKS_KEY = "library-works"; // { [workId]: Work }
const LISTS_KEY = "library-lists"; // [List, ...]

// Work: { id, title, source: 'local'|'drive'|'imslp', fileName, addedAt, lastOpenedAt, pages }
// List: { id, name, workIds: [], createdAt, updatedAt }

export function getWorks() {
  return store.get(WORKS_KEY, {});
}

export function getWork(workId) {
  return getWorks()[workId] || null;
}

// Registers a work the first time it's opened, or bumps lastOpenedAt/pages
// on subsequent opens — idempotent, safe to call on every open flow.
export function upsertWork(partial) {
  const works = getWorks();
  const existing = works[partial.id];
  const merged = {
    ...existing,
    ...partial,
    addedAt: existing?.addedAt ?? partial.addedAt ?? Date.now(),
    lastOpenedAt: Date.now(),
  };
  works[partial.id] = merged;
  store.set(WORKS_KEY, works);
  return merged;
}

export function deleteWork(workId) {
  const works = getWorks();
  delete works[workId];
  store.set(WORKS_KEY, works);
  // Remove it from every list too, so lists never dangle on a deleted work
  const lists = getLists().map(l => ({ ...l, workIds: l.workIds.filter(id => id !== workId) }));
  store.set(LISTS_KEY, lists);
}

export function getLists() {
  return store.get(LISTS_KEY, []);
}

export function createList(name) {
  const lists = getLists();
  const list = { id: `list-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, name, workIds: [], createdAt: Date.now(), updatedAt: Date.now() };
  store.set(LISTS_KEY, [...lists, list]);
  return list;
}

export function renameList(listId, name) {
  const lists = getLists().map(l => l.id === listId ? { ...l, name, updatedAt: Date.now() } : l);
  store.set(LISTS_KEY, lists);
}

export function deleteList(listId) {
  store.set(LISTS_KEY, getLists().filter(l => l.id !== listId));
}

export function reorderLists(orderedIds) {
  const lists = getLists();
  const byId = new Map(lists.map(l => [l.id, l]));
  store.set(LISTS_KEY, orderedIds.map(id => byId.get(id)).filter(Boolean));
}

export function addWorkToList(listId, workId) {
  const lists = getLists().map(l => {
    if (l.id !== listId || l.workIds.includes(workId)) return l;
    return { ...l, workIds: [...l.workIds, workId], updatedAt: Date.now() };
  });
  store.set(LISTS_KEY, lists);
}

export function removeWorkFromList(listId, workId) {
  const lists = getLists().map(l => l.id === listId
    ? { ...l, workIds: l.workIds.filter(id => id !== workId), updatedAt: Date.now() }
    : l);
  store.set(LISTS_KEY, lists);
}

export function reorderWorksInList(listId, orderedWorkIds) {
  const lists = getLists().map(l => l.id === listId
    ? { ...l, workIds: orderedWorkIds, updatedAt: Date.now() }
    : l);
  store.set(LISTS_KEY, lists);
}

export function listsContainingWork(workId) {
  return getLists().filter(l => l.workIds.includes(workId));
}
