import { drawStamp } from "./stamps";

// ── Freehand stroke drawing + per-page item dispatch ──────────────────────
// `redrawAll` renders a page's full annotation array — freehand strokes AND
// stamps share the same array (discriminated by `item.type`), so undo/redo
// (which snapshot/restore that whole array) needed no changes to support
// stamps — see stamps.js for the stamp shape and rendering.
//
// Every item's stored x/y/points are in ZOOM-INDEPENDENT coordinates (the
// page's own scale=1 space) — `scale` (always the current zoom) is applied
// only here, at the final draw-to-canvas step, so a stroke drawn at one
// zoom level stays correctly anchored to the page at any other zoom
// instead of only looking right at the zoom it was drawn at.

export function drawStroke(ctx, stroke, scale = 1) {
  if (!stroke.points || stroke.points.length < 2) return;
  ctx.save();
  ctx.globalCompositeOperation = stroke.tool === "eraser" ? "destination-out" : "source-over";
  ctx.strokeStyle = stroke.color;
  ctx.lineWidth   = stroke.width * scale;
  ctx.lineCap     = "round";
  ctx.lineJoin    = "round";
  ctx.globalAlpha = stroke.tool === "highlight" ? 0.45 : 1;
  const pt = (p) => ({ x: p.x * scale, y: p.y * scale });
  ctx.beginPath();
  const p0 = pt(stroke.points[0]);
  ctx.moveTo(p0.x, p0.y);
  for (let i = 1; i < stroke.points.length; i++) {
    const a = pt(stroke.points[i - 1]), b = pt(stroke.points[i]);
    const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
    ctx.quadraticCurveTo(a.x, a.y, mid.x, mid.y);
  }
  ctx.stroke();
  ctx.restore();
}

export function drawItem(ctx, item, selectedId, scale = 1) {
  if (item.type === "stamp") { drawStamp(ctx, item, item.id === selectedId, scale); return; }
  drawStroke(ctx, item, scale); // default — freehand stroke (legacy items have no `type` at all)
}

export function redrawAll(canvas, items, selectedId, scale = 1) {
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  items.forEach(it => drawItem(ctx, it, selectedId, scale));
}

export const ptDist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
